// Вход: сообщение из Telegram или тестовый вызов (webhook для автотестов).
// Клиент определяется по номеру телефона: Telegram присылает его, когда клиент
// нажимает кнопку «Поделиться номером». Связка chat id -> телефон хранится в таблице aiva_clients_tg.
const MADINA_CHAT_ID = 'YOUR_TELEGRAM_CHAT_ID';   // кому уходят уведомления о переводе и об ошибках
const TEST_KEY = 'YOUR_TEST_KEY';       // ключ тестового входа: без него вызов игнорируется

// Телефон в формате таблицы «Список клиентов»: только цифры, 11 знаков, начинается с 7.
const normPhone = (p) => {
  let d = String(p || '').replace(/\D/g, '');
  if (d.length === 11 && d.startsWith('8')) d = '7' + d.slice(1);
  if (d.length === 10) d = '7' + d;
  return d;
};

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  if (j.message) {
    const m = j.message;
    const own = m.contact && (!m.contact.user_id || m.contact.user_id === m.from?.id);
    out.push({ json: {
      source: 'telegram', testCase: '',
      chatId: String(m.chat?.id ?? ''),
      firstName: m.from?.first_name || '',
      textMessage: m.text || '',
      sharedPhone: own ? normPhone(m.contact.phone_number) : '',
      testPhone: '', client: {},
      receivedAt: m.date ? m.date * 1000 : Date.now(),
      madinaChatId: MADINA_CHAT_ID,
    } });
  } else {
    const b = j.body || {};
    if (b.key !== TEST_KEY) continue;
    if (b.forceError) throw new Error('Тестовая ошибка: проверка обработчика ошибок (кейс ' + b.case + ')');
    out.push({ json: {
      source: 'test', testCase: String(b.case || ''),
      chatId: 'test-' + (b.case || Date.now()),
      firstName: b.firstName || 'Тест',
      textMessage: b.text || '',
      sharedPhone: b.sharePhone ? normPhone(b.sharePhone) : '',
      testPhone: normPhone(b.phone || ''), client: b.client || {},
      receivedAt: Date.now(),
      madinaChatId: MADINA_CHAT_ID,
      ...(b.hour !== undefined ? { hourOverride: Number(b.hour) } : {}),
    } });
  }
}
return out;

// Данные клиента для агента: строка из «Списка клиентов» или профиль нового клиента.
const inp = $('Вход: Telegram или тест').item.json;
const row = $json || {};
const found = !!row.Телефон;
const client = found ? row : {
  Имя_Отчество: inp.firstName || 'клиент',
  Телефон: $('Телефон клиента').item.json.phone,
  Категория: 'Клиент',
  Статус: 'Новый',
};
return { json: {
  ...client, ...inp.client,
  chatId: inp.chatId, textMessage: inp.textMessage,
  ...(inp.hourOverride !== undefined ? { hourOverride: inp.hourOverride } : {}),
} };

const staticData = $getWorkflowStaticData('global');
if (!staticData.lastMessageTime) staticData.lastMessageTime = {};
const chatId = $json.chatId;
const ts = Date.now();
staticData.lastMessageTime[chatId] = ts;
return { json: { ...$json, _debounceTs: ts } };

const staticData = $getWorkflowStaticData('global');
const chatId = $json.chatId;
if (staticData.lastMessageTime[chatId] !== $json._debounceTs) {
  return null;
}
return { json: $json };

